CREATE TABLE growth_notifications(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,report_id TEXT NOT NULL,revision_id TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,report_id) REFERENCES growth_reports(tenant_id,id),FOREIGN KEY(tenant_id,revision_id) REFERENCES growth_report_revisions(tenant_id,id));
